"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[6235],{86235:a=>{a.exports=JSON.parse('{"slug":"samsung-rekord-pamyat-smartfony-ceny","locale":"zh","title":"存储短缺使Samsung季度利润创$80十亿纪录，手机却更贵","description":"Samsung在2026年第三季度获得107.4万亿韩元营业利润。为何AI存储需求推高全球与俄罗斯手机价格。","blocks":[{"id":"b001","kind":"paragraph","text":"Samsung Electronics于2026年十月8日预估第三季度营业利润107.4万亿韩元，约$80.2十亿；去年同期12.2万亿，近9倍。营收增逾2倍至约195万亿。此前纪录是2026年第二季度89.5万亿。分析师预期略高，约108万亿。"},{"id":"b002","kind":"paragraph","text":"利润增长来自存储，尤其AI服务器存储。它与普通手机、笔记本存储在同样工厂生产，售价却高得多。类似餐厅付的蛋糕价是商店面包的3倍，烤炉不变，面包自然少做。新厂需数年；生产普通存储而放弃服务器存储的利润，称机会成本。"},{"id":"b003","kind":"paragraph","text":"2026年第二季度移动存储价格较2025年第四季度近3倍。2026年以来全球超过40%手机型号涨价，平均15%；2026新款比去年贵25%。产销均下降：Counterpoint六月下调预测，预计2026出货少13.9%至1.08十亿部。Samsung的Galaxy手机部门在第二季度首次营业亏损0.7万亿韩元，原因正是存储昂贵。"},{"id":"b004","kind":"paragraph","text":"俄罗斯2026年前37周售15.2百万部，同比少11.7%；均价升7.6%至25.8千卢布，既受标价也受消费者选择影响。低端机节省内存：九月发布Redmi 17，18千卢布起却仅4GB。九月29日至十月5日俄罗斯手机涨1.1%，电视1%。设备进口，而十月1日至6日官方美元从83.56升84.93卢布，周涨价未必全因存储。"},{"id":"b005","kind":"paragraph","text":"TrendForce预计2026年第四季度普通存储合约价较第三季度再涨10–15%，闪存15–20%。Samsung存储高管金在俊预计短缺贯穿2026及2027大部分，可能延至2028。SK hynix负责人郭鲁正称2027可能是行业史上存储供应最差一年。"},{"id":"b006","kind":"paragraph","text":"现在买手机比一年前贵。可以延期，但制造商自己也预计2027存储仍缺。卢布走强能缓和涨价，走弱则加剧。"},{"id":"b007","kind":"heading","text":"2026年智能手机为何涨价？"},{"id":"b008","kind":"paragraph","text":"存储短缺。制造商转产更贵的AI服务器存储，手机普通存储不足。2026年第二季度移动存储较2025年末近3倍，而全球手机年初以来平均涨15%。"},{"id":"b009","kind":"heading","text":"俄罗斯手机涨多少？"},{"id":"b010","kind":"paragraph","text":"2026年前37周，购买均价增7.6%至25.8千卢布，销量少11.7%。九月29日至十月5日手机涨1.1%。"},{"id":"b011","kind":"heading","text":"存储短缺何时结束？"},{"id":"b012","kind":"paragraph","text":"制造商未承诺。Samsung预计整个2026及2027大部分，可能延至2028；SK hynix称2027可能为行业史上供应最差。"}],"sources":[{"label":"Samsung预计2026年第3季度营业利润创$80十亿纪录","url":"https://sammyguru.com/samsung-estimates-record-80-billion-operating-profit-q3-2026/"},{"label":"AI热潮推动芯片需求，Samsung预测第三季度利润$80十亿","url":"https://www.cnbc.com/2026/10/08/samsung-q3-earnings.html"},{"label":"AI芯片使Samsung季度利润增九倍至约$80十亿","url":"https://startupfortune.com/samsungs-quarterly-profit-jumped-ninefold-to-roughly-80-billion-on-ai-chips/"},{"label":"Samsung Galaxy手机部门首次季度亏损","url":"https://www.phonearena.com/news/samsung-mobile-experience-unit-first-quarterly-loss_id182207"},{"label":"未来更差：全球手机价格失控上涨","url":"https://www.cnews.ru/news/top/2026-09-04_dalshe_budet_huzhev_mire"},{"label":"存储紧缩冻结手机市场：2026出货预计跌13.9%","url":"https://finance.biggo.com/news/o46al54B6tLPsnrZsogu"},{"label":"AI服务器需求支撑4Q26存储合约价上涨","url":"https://www.trendforce.com/presscenter/news/20260930-13258.html"},{"label":"俄罗斯消费者购买更少手机","url":"https://3dnews.ru/1149266"},{"label":"俄罗斯九月29日至十月5日通胀","url":"https://www.vedomosti.ru/economics/news/2026/10/07/1235202-inflyatsiya-v-rossii"},{"label":"Samsung警告内存短缺持续至2027，可能2028","url":"https://www.pcworld.com/article/3203764/samsung-warns-the-ram-shortage-will-last-through-2027-maybe-2028.html"},{"label":"SK hynix警告2027年存储短缺或为历史最严重","url":"https://propakistani.pk/2026/07/13/sk-hynix-warns-memory-shortage-will-be-worst-ever-in-2027/"}],"sourceBodySha256":"9109ae1c3a0a697fc17c90fd75c97bd35553c9ab1d7901b4a84036a4db6a8302"}')}}]);